const $=s=>document.querySelector(s);
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={camera:'M4 7h4l2-3h4l2 3h4v13H4z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M16 8l-3 5-5 3 3-5z',map:'M3 5l6-2 6 2 6-2v16l-6 2-6-2-6 2z M9 3v16 M15 5v16',book:'M4 3h13a3 3 0 0 1 3 3v15H7a3 3 0 0 1-3-3z M4 17h16 M8 7h8 M8 11h5',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M4 12h15 M14 7l5 5-5 5',leaf:'M20 3C8 2 3 7 4 14c1 7 15 7 16-11 M5 19L16 8',users:'M9 11a4 4 0 1 1 0-8 4 4 0 0 1 0 8 M2 21v-3a7 7 0 0 1 14 0v3 M17 4a4 4 0 0 1 0 8 M19 15a6 6 0 0 1 3 6',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',check:'M5 12l4 4L19 6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',play:'M7 4l13 8-13 8z',walk:'M12 3v1 M8 9l4-3 4 4h4 M12 6l-2 7 5 3 1 6 M10 13l-4 8',edit:'M15 4l5 5 M4 20l5-1L21 7l-5-5L4 14z',pause:'M8 4v16 M16 4v16',logout:'M9 4H3v16h6 M8 12h13 M16 7l5 5-5 5',refresh:'M20 7v5h-5 M4 17v-5h5 M5 8a8 8 0 0 1 14-3l1 7 M4 12l1 7a8 8 0 0 0 14-3',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.compass}"/></svg>`;
const state={catalog:null,sessions:[],plans:[],preferences:{budget:20,people:1,intensity:'轻松',theme:'全部',mode:'personal'},admin:null,route:location.hash.slice(1)|| (location.pathname==='/admin'?'admin':'explore')};
let toastTimer,requestNumber=0;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3800);}
async function api(url,method='GET',data){const res=await fetch(url,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const body=await res.json();if(!res.ok)throw Error(body.error||'操作失败，请重试');return body;}
async function load(){[state.catalog,state.sessions]=await Promise.all([api('/api/catalog'),api('/api/sessions')]);state.plans=await api('/api/plan','POST',state.preferences);}
const active=()=>state.sessions.find(s=>['active','paused'].includes(s.status));
function navLink(to,title,name){return `<a href="#${to}" class="${state.route===to?'active':''}" ${state.route===to?'aria-current="page"':''}>${icon(name)}${title}</a>`;}
function layout(content){const admin=state.route.startsWith('admin');const labels={explore:'发现路线',experience:'我的探索',memories:'探索手记',points:'校园点位',admin:'管理概览','admin-points':'点位管理','admin-routes':'路线管理','admin-templates':'任务模板','admin-feedback':'体验与反馈','admin-logs':'生成与校验'};
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#explore"><span class="brand-mark">${icon('camera')}</span><span><strong>探索与拍摄</strong><small>EXPLORE & CAPTURE</small></span></a><div class="nav-label">${admin?'内容工作台':'我的校园手记'}</div><nav class="nav" aria-label="主导航">${admin?navLink('admin','管理概览','grid')+navLink('admin-points','点位管理','pin')+navLink('admin-routes','路线管理','map')+navLink('admin-templates','任务模板','book')+navLink('admin-feedback','体验反馈','users')+navLink('admin-logs','生成校验','shield'):navLink('explore','发现路线','compass')+navLink('experience','我的探索','map')+navLink('memories','探索手记','book')+navLink('points','校园点位','pin')}</nav><div class="sidebar-bottom"><div class="side-note">${icon('leaf')}<strong>一小段路，一点新发现</strong><p>带上手机，留一点时间给校园。</p></div><a class="admin-link" href="#${admin?'explore':'admin'}">${icon(admin?'compass':'shield')}${admin?'返回用户端':'进入管理端'} ${icon('arrow')}</a></div></aside><main class="main"><header class="topbar"><div class="crumb"><span class="muted">${admin?'内容管理':'校园探索'}</span><span class="muted">/</span><span>${labels[state.route]||'探索手记'}</span></div><div class="user-chip"><span class="badge">本地体验版</span><a class="mobile-brand" href="#${admin?'explore':'admin'}">${admin?'用户端':'管理端'}</a><span class="avatar">${admin?'管':'探'}</span><span>${admin?'内容管理员':'校园探索者'}</span>${admin&&state.catalog.admin?'<button class="text-btn" data-action="logout">退出</button>':''}</div></header><div class="content">${content}<footer class="footer"><span>探索与拍摄 · 校园探索智能互动系统</span><span>示范片区 / 非真实导航</span></footer></div></main></div>`;
}
function heading(eyebrow,title,desc,aside=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div><div class="heading-aside">${aside}</div></div>`;}
function segmented(key,values){return `<div class="segmented">${values.map(([v,label])=>`<button data-pref="${key}" data-value="${v}" aria-pressed="${state.preferences[key]===v}" class="${state.preferences[key]===v?'selected':''}">${label}</button>`).join('')}</div>`;}
function mapSvg(ids=['p1','p2','p3']){const points=state.catalog.points;return `<div class="map"><svg viewBox="0 0 260 238" role="img" aria-label="示意路线图，非真实导航"><defs><pattern id="mapgrid" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M22 0H0V22" stroke="#e3ebdb" fill="none"/></pattern></defs><rect width="260" height="238" fill="url(#mapgrid)"/><path d="M0 180L260 70 M30 0L140 238 M0 80L260 180" stroke="#fff" stroke-width="17" fill="none"/><path d="M0 180L260 70 M30 0L140 238 M0 80L260 180" stroke="#e6eadd" stroke-width="1" fill="none"/><polyline points="${ids.map(id=>{const p=points.find(p=>p.id===id);return `${p.x*2.6},${p.y*2.38}`;}).join(' ')}" stroke="#829c59" stroke-width="3" stroke-dasharray="5 5" fill="none"/>${points.map(p=>{const i=ids.indexOf(p.id);return `<g><circle cx="${p.x*2.6}" cy="${p.y*2.38}" r="${i>=0?11:5}" fill="${i>=0?'#285b49':'#c0cfad'}" stroke="white" stroke-width="3"/>${i>=0?`<text x="${p.x*2.6}" y="${p.y*2.38+4}" font-size="10" text-anchor="middle" fill="white">${i+1}</text>`:''}</g>`;}).join('')}<text x="18" y="24" font-size="10" fill="#91a081">N ↑</text><text x="130" y="225" font-size="10" text-anchor="middle" fill="#829279">示范片区 · 路线关系示意</text></svg></div>`;}
function empty(title,desc,button=''){return `<div class="empty">${icon('compass')}<h2>${title}</h2><p>${desc}</p>${button}</div>`;}
function pointNames(r){return r.points.map(id=>state.catalog.points.find(p=>p.id===id)?.name||id);}
function explore(){const p=state.preferences;const recommended=state.plans.find(r=>r.available&&r.match)||state.plans.find(r=>r.available);const rest=state.plans.filter(r=>r!==recommended);const s=active();
 layout(`${heading('LET’S GO OUTSIDE','给日常，换一个视角','选一段空闲时间，用镜头发现校园里被忽略的小美好。','8 个点位 · 3 条探索路线')}${s?`<div class="session-banner"><span>你有一段${s.status==='paused'?'已暂停':'未完成'}的探索：${E(s.routeName)}</span><a class="btn sm" href="#experience">继续探索 ${icon('arrow')}</a></div>`:''}<div class="explore-layout"><div class="primary-column"><section class="preferences"><div class="section-label">${icon('compass')}今天，想怎样探索？</div><div class="pref-grid"><div><label class="field-title">可用时间</label>${segmented('budget',[[15,'15 分钟'],[20,'20 分钟'],[30,'30 分钟']])}</div><div><label class="field-title">同行人数</label>${segmented('people',[[1,'独自出发'],[2,'结伴同行']])}</div><div><label class="field-title">步行强度</label>${segmented('intensity',[['轻松','轻松散步'],['适中','多走一点']])}</div></div><div class="pref-footer"><div class="inline"><span class="field-title" style="margin:0">感兴趣的主题</span><div class="chips">${['全部','建筑','自然','人文'].map(t=>`<button class="chip ${t===p.theme?'selected':''}" data-pref="theme" data-value="${t}" aria-pressed="${t===p.theme}">${t==='全部'?'随心探索':t}</button>`).join('')}</div></div><span class="small">${icon('shield')} 自动检查时间预算</span></div></section><div class="section-head"><h2>为你推荐的路线</h2><span>${state.plans.filter(r=>r.available).length} 条符合当前时间与强度</span></div>${recommended?routeCard(recommended,true):empty('还没有适合的路线','试试增加时间预算、选择“多走一点”，或等待点位重新开放。')}<div class="section-head"><h2>更多探索灵感</h2><span>校园，还有另一面</span></div>${rest.map(r=>routeCard(r,false)).join('')}<div class="notice">当前为虚构校园示范资料，时间与点位均待实地核实；路线图用于演示顺序，不提供导航。</div></div><aside class="rail"><section class="panel map-panel"><h3>探索片区一览 <span class="badge gray">示意</span></h3>${mapSvg(recommended?.points)}<div class="map-legend"><span><i></i>当前路线</span><span><i style="background:#c0cfad"></i>其他点位</span></div><p class="map-caption">点击路线详情，查看停留顺序与每一站的拍摄条件。</p></section><section class="panel tip-panel"><div class="tip-icon">${icon('sun')}</div><h3>不必走很远，<br>好风景就在身边。</h3><p>试着把镜头放低一点，观察光落在建筑和树叶上的样子。</p><div class="tip-bottom"><span>今日拍摄灵感</span>${icon('camera')}</div></section><section class="panel how-panel"><h3>一段探索，三个小步骤</h3>${[['选择一条路线','按时间与兴趣，找到今天的方向'],['带着任务出发','观察、拍摄，也可以随时暂停'],['留下一页回忆','上传照片，保存专属探索手记']].map(([t,d],i)=>`<div class="how-item"><span class="num">0${i+1}</span><div><b>${t}</b><p>${d}</p></div></div>`).join('')}</section></aside></div>`);
}
function routeCard(r,feature){if(!feature)return `<article class="route-card compact-route"><div class="route-number">0${Number(r.id.slice(1))}</div><div><h3>${E(r.name)}</h3><p>${r.total} 分钟 · ${r.points.length} 个点位 · ${r.available?'适合当前偏好':E(r.reason)}</p></div><button class="btn outline" data-action="route" data-id="${r.id}">查看路线 ${icon('arrow')}</button></article>`;return `<article class="route-card"><div class="route-cover"><img src="/assets/campus.jpg" alt="虚构校园的林荫步道与教学建筑，AI 生成示意图"><span class="cover-badge">${r.match?'适合你的节奏':'也可以试试'} · ${r.theme}</span><div class="cover-caption"><span>示范校园 · 中心片区</span><span>AI 生成配图</span></div></div><div class="route-body"><div class="route-heading"><h2>${E(r.name)}</h2><span class="badge">${r.intensity}散步</span></div><p class="route-description">${E(r.subtitle)}</p><div class="route-meta"><span>${icon('clock')}${r.total} 分钟 · 含缓冲</span><span>${icon('walk')}约 ${r.distance} 米</span><span>${icon('pin')}${r.points.length} 个探索点</span><span>${icon('camera')}${r.points.length} 个拍摄任务</span></div><div class="route-stops">${pointNames(r).map((n,i)=>`${i?'<i>—</i>':''}<span>${i+1}. ${E(n)}</span>`).join('')}</div><div class="route-actions"><button class="text-btn" data-action="route" data-id="${r.id}">查看路线与时间分配</button><button class="btn primary" data-action="route" data-id="${r.id}">开启这段探索 ${icon('arrow')}</button></div></div></article>`;}
function modal(html){$('#modal').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function routeDetail(id){const r=state.plans.find(r=>r.id===id);modal(`<div class="dialog-head"><div><div class="eyebrow">ROUTE ${id.toUpperCase()}</div><h2>${E(r.name)}</h2></div><button class="close" data-action="close" aria-label="关闭">×</button></div><div class="time-breakdown">${[[r.walk,'步行'],[r.stay,'任务停留'],[r.buffer,'预算缓冲'],[r.total,'总计']].map(([v,l])=>`<div><b>${v}<small> 分</small></b><span>${l}</span></div>`).join('')}</div>${r.points.map((id,i)=>{const p=state.catalog.points.find(p=>p.id===id);return `<div class="detail-line"><b>${i+1}</b><div><h3>${E(p.name)} ${p.open?'':'· 已关闭'}</h3><p>${E(p.condition)}</p></div></div>`;}).join('')}<label class="form-field">体验方式<select id="experience-mode"><option value="personal" ${state.preferences.mode==='personal'?'selected':''}>个性化任务（本地模板模式）</option><option value="fixed" ${state.preferences.mode==='fixed'?'selected':''}>固定拍摄任务</option><option value="guide" ${state.preferences.mode==='guide'?'selected':''}>普通点位导览</option></select></label><div class="notice">未配置 AI 接口时自动回退到审核模板。点位、路径与时长由程序检查；示范数据不能直接用于实地体验。</div>${!r.available?`<p class="error">${E(r.reason)}</p>`:''}<div class="dialog-actions"><button class="btn outline" data-action="close">再看看</button><button class="btn primary" data-action="start" data-id="${r.id}" ${r.available?'':'disabled'}>确认开始 ${icon('arrow')}</button></div>`);}
function pointsView(){layout(`${heading('CAMPUS SPOTS','把校园，慢慢看清楚','每一个点位都带着可观察的细节，也有需要遵守的边界。')}<div class="notice">下列点位为虚构示范，来源、开放条件和核实日期可在管理端维护。</div><div class="grid3">${state.catalog.points.map((p,i)=>`<article class="point-card"><div class="point-head"><span class="eyebrow">SPOT ${String(i+1).padStart(2,'0')}</span><span class="badge ${p.open?'':'warn'}">${p.open?'演示开放':'暂时关闭'}</span></div><h3>${E(p.name)}</h3><p class="space">${E(p.fact)}</p><small>${E(p.condition)}</small><div class="inline"><span class="badge gray">${p.theme}</span><span class="small">${p.verifiedAt?'核实 '+E(p.verifiedAt):'待实地核实'}</span></div></article>`).join('')}</div>`);}
async function render(){if(!state.catalog)return;document.title=(state.route.startsWith('admin')?'管理端':'用户端')+' · 探索与拍摄';if(state.route==='explore')explore();else if(state.route==='points')pointsView();else if(state.route==='experience')experience();else if(state.route==='memories')memories();else if(state.route.startsWith('admin'))await adminView();else{state.route='explore';explore();}}
window.addEventListener('hashchange',async()=>{state.route=location.hash.slice(1)||'explore';closeModal();try{await load();await render();window.scrollTo(0,0);}catch(e){toast(e.message);}});
document.addEventListener('click',async event=>{const pref=event.target.closest('[data-pref]');if(pref){state.preferences[pref.dataset.pref]=['budget','people'].includes(pref.dataset.pref)?Number(pref.dataset.value):pref.dataset.value;const n=++requestNumber;try{const plans=await api('/api/plan','POST',state.preferences);if(n===requestNumber){state.plans=plans;explore();}}catch(e){toast(e.message);}return;}const btn=event.target.closest('[data-action]');if(!btn)return;const {action,id}=btn.dataset;try{if(action==='close')closeModal();else if(action==='route')routeDetail(id);else if(action==='start'){btn.disabled=true;state.preferences.mode=$('#experience-mode').value;await api('/api/sessions','POST',{routeId:id,preferences:state.preferences});closeModal();location.hash='experience';}else await handleAction(action,id,btn);}catch(e){toast(e.message);btn.disabled=false;}});
const statusText={active:'探索中',paused:'已暂停',completed:'已完成',ended:'已结束',done:'已完成',skipped:'已跳过',pending:'待完成'};
const modeText={guide:'普通导览',fixed:'固定任务',personal:'个性化模板'};
function timeString(s){const secs=Math.floor((s.elapsed+(s.status==='active'?Date.now()-s.lastResume:0))/1000);return String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0');}
function experience(){const s=active();if(!s){layout(`${heading('YOUR EXPLORATION','下一段探索，等你出发','选一条路线，从一个小小的发现开始。')}${empty('还没有进行中的探索','已经完成的探索，可以在“探索手记”中查看。','<a class="btn primary" href="#explore">去发现路线 '+icon('arrow')+'</a>')}`);return;}
 const done=s.tasks.filter(t=>t.status==='done').length,processed=s.tasks.filter(t=>t.status!=='pending').length;layout(`${heading('YOUR EXPLORATION',E(s.routeName),`${s.preferences.people===2?'结伴同行':'独自探索'} · ${E(s.preferences.theme)}主题 · 资料版本 v${s.version}`,`<span class="badge">${statusText[s.status]}</span>`)}${s.blocked.length?`<div class="notice warn">${icon('shield')} ${s.blocked.map(E).join('、')} 已关闭，剩余任务已停止。当前没有核实过的替代路线，请结束本次体验后重新选择。</div>`:''}<div class="notice">${E(s.generation)}。任务采用手动自报完成，照片仅本人可见。</div><div class="task-layout"><div>${s.tasks.map((t,i)=>`<article class="task ${t.status==='done'?'done':''}"><div class="task-top"><span class="task-number">TASK ${String(i+1).padStart(2,'0')} / ${E(t.pointName)}</span><span class="badge ${t.status==='pending'?'gray':t.status==='skipped'?'warn':''}">${statusText[t.status]}</span></div><h2>${E(t.title)}</h2><ol>${t.steps.map(step=>`<li>${E(step)}</li>`).join('')}</ol><div class="condition">${E(t.condition)} · 预计停留 ${t.minutes} 分钟</div>${t.photo?`<img class="task-photo" src="${t.photo}" alt="${E(t.pointName)}的探索照片">`:''}<div class="task-actions">${t.status==='pending'?`<button class="btn primary" data-action="complete" data-id="${t.id}" ${s.status==='paused'||s.blocked.length?'disabled':''}>${icon('check')} 标记完成</button><button class="btn outline" data-action="skip" data-id="${t.id}" ${s.status==='paused'||s.blocked.length?'disabled':''}>跳过任务</button>`:`<span class="small">${t.status==='done'?'已记录你的发现':'跳过原因：'+E(t.reason)}</span>`}<button class="btn outline" data-action="upload" data-id="${s.id}:${t.id}">${icon('camera')} ${t.photo?'替换照片':'上传照片'}</button>${t.photo?`<button class="text-btn" data-action="remove-photo" data-id="${s.id}:${t.id}">移除照片</button>`:''}</div></article>`).join('')}</div><aside><section class="panel sticky-panel"><h3>这段路，慢慢走</h3><span class="small">${s.status==='paused'?'计时已暂停':'已探索时间'}</span><div class="timer" id="timer">${timeString(s)}</div><span class="small">时间预算 ${s.preferences.budget} 分钟 · 预计 ${s.plan.total} 分钟</span><div class="progress-track"><div class="progress-fill" style="width:${processed/s.tasks.length*100}%"></div></div><p class="small">${done} 项完成 · ${processed-done} 项跳过 · 共 ${s.tasks.length} 项</p><div class="inline space"><button class="btn outline" data-action="${s.status==='paused'?'resume':'pause'}" data-id="${s.id}">${icon(s.status==='paused'?'play':'pause')}${s.status==='paused'?'恢复探索':'暂停探索'}</button><button class="text-btn" data-action="refresh-session">刷新状态</button></div><button class="btn primary full space" data-action="finish" data-id="${s.id}" ${processed<s.tasks.length?'disabled':''}>完成探索，留下回忆 ${icon('arrow')}</button><button class="text-btn full" data-action="exit" data-id="${s.id}">提前结束这次探索</button></section></aside></div>`);}
function memories(){const sessions=[...state.sessions].reverse();layout(`${heading('MY FIELD NOTES','探索手记','那些走过的路、按下的快门，都留在这里。',`${sessions.length} 段探索记录`)}<div class="notice">照片与手记保存在本机，当前浏览器身份可见。可下载独立 HTML 手记，或随时删除记录。</div>${sessions.length?`<div class="grid2">${sessions.map(s=>{const photo=s.tasks.find(t=>t.photo)?.photo;return `<article class="route-card">${photo?`<div class="route-cover"><img src="${photo}" alt="${E(s.routeName)}的探索照片"></div>`:''}<div class="route-body"><div class="route-heading"><h2>${E(s.routeName)}</h2><span class="badge ${s.status==='ended'?'gray':''}">${statusText[s.status]}</span></div><div class="record-meta"><span class="small">${new Date(s.createdAt).toLocaleDateString('zh-CN')}</span><span class="small">${s.tasks.filter(t=>t.status==='done').length}/${s.tasks.length} 任务</span><span class="small">${s.tasks.filter(t=>t.photo).length} 张照片</span><span class="small">${s.preferences.people} 人同行</span></div><p class="route-description">${E(s.feedback||'今天有什么新发现？写下你的感受吧。')}</p><div class="route-actions space"><button class="btn outline" data-action="record" data-id="${s.id}">查看与编辑</button><a class="btn primary" href="/api/sessions/${s.id}/export" download>${icon('download')} 下载手记</a></div></div></article>`;}).join('')}</div>`:empty('你的第一张手记，留给下一次出发','完成探索后，在这里整理照片、写下感受并下载。','<a class="btn primary" href="#explore">发现一条路线 '+icon('arrow')+'</a>')}`);}
function recordDetail(id){const s=state.sessions.find(s=>s.id===id);modal(`<div class="dialog-head"><div><div class="eyebrow">MY FIELD NOTES</div><h2>${E(s.routeName)}</h2></div><button class="close" data-action="close" aria-label="关闭">×</button></div><p class="small">${statusText[s.status]} · ${timeString(s)} · 资料版本 v${s.version}</p>${s.tasks.map(t=>`<div class="task space"><div class="task-top"><b>${E(t.pointName)}</b><span class="badge gray">${statusText[t.status]}</span></div><p class="small">${E(t.title)}</p>${t.photo?`<img class="task-photo" src="${t.photo}" alt="${E(t.pointName)}的照片">`:''}<button class="btn outline sm space" data-action="upload" data-id="${s.id}:${t.id}">${icon('camera')}${t.photo?'替换':'添加'}照片</button>${t.photo?`<button class="text-btn" data-action="remove-photo" data-id="${s.id}:${t.id}">移除照片</button>`:''}</div>`).join('')}<form id="feedback-form" data-id="${s.id}"><label class="form-field">这次探索的感受<textarea name="feedback" maxlength="2000" placeholder="哪一站最有意思？任务是否容易理解？">${E(s.feedback)}</textarea></label><label class="form-field">整体体验<select name="rating">${[[0,'暂不评分'],[5,'5 · 很喜欢'],[4,'4 · 不错'],[3,'3 · 一般'],[2,'2 · 需要改进'],[1,'1 · 不满意']].map(([n,l])=>`<option value="${n}" ${s.rating===n?'selected':''}>${l}</option>`).join('')}</select></label><p class="error" id="form-error"></p><div class="dialog-actions"><button type="button" class="btn danger" data-action="delete-record" data-id="${s.id}">${icon('trash')} 删除</button><button class="btn primary" type="submit">保存手记</button></div></form>`);}
async function adminView(){if(!state.catalog.admin){layout(`<div class="login-panel"><span class="brand-mark">${icon('shield')}</span><h1>把每一段探索准备好</h1><p>登录管理端，维护点位、审核任务，并查看真实产生的体验反馈。</p><form id="login-form"><label class="form-field">管理员账号<input name="username" autocomplete="username" value="admin" required></label><label class="form-field">密码<input type="password" name="password" autocomplete="current-password" placeholder="输入管理密码" required></label><p class="error" id="form-error"></p><button class="btn primary" type="submit">进入管理工作台 ${icon('arrow')}</button></form><p class="small space">本地演示账号：admin<br>演示密码：Explore2026!</p><a class="text-btn" href="#explore">返回用户端</a></div>`);return;}
 try{state.admin=await api('/api/admin');}catch(e){state.catalog.admin=false;return adminView();}const d=state.admin;
 if(state.route==='admin'){const completed=d.sessions.filter(s=>s.status==='completed'),tasks=d.sessions.flatMap(s=>s.tasks);layout(`${heading('CONTENT WORKSPACE','让每次出发，都有据可依','从点位核查到任务审核，在这里维护一段可靠的探索体验。',`资料版本 v${d.version}`)}<div class="grid3">${[[d.points.filter(p=>p.open).length,'开放点位',`共 ${d.points.length} 个示范点位`],[d.routes.filter(r=>r.active).length,'启用路线','15—30 分钟短路线'],[d.templates.filter(t=>t.approved).length,'已审核模板',`共 ${d.templates.length} 个任务模板`]].map(([n,l,s])=>`<div class="metric"><span>${l}</span><b>${n.toString().padStart(2,'0')}</b><span>${s}</span></div>`).join('')}</div><div class="grid2 space"><section class="panel"><h3>资料核查进度</h3><div class="admin-message"><p>${d.points.filter(p=>p.verifiedAt).length} / ${d.points.length} 个点位填写了核实日期</p><small>演示点位不等于现场核查完成，正式试用前请替换来源。</small></div><div class="admin-message"><p>${d.routes.filter(r=>r.timings.length>=3).length} / 3 条路线完成三次计时记录</p><small>记录至少三次实走耗时，用于调整路线估时。</small></div><div class="inline space"><a class="btn outline" href="#admin-points">维护点位</a><a class="btn primary" href="#admin-routes">维护路线</a></div></section><section class="panel"><h3>本机体验概况</h3><div class="inline"><div class="metric" style="border:0;padding:5px 20px 5px 0"><b>${d.sessions.length}</b><span>发起探索</span></div><div class="metric" style="border:0;padding:5px"><b>${completed.length}</b><span>完成路线</span></div><div class="metric" style="border:0;padding:5px"><b>${tasks.length?Math.round(tasks.filter(t=>t.status==='done').length/tasks.length*100):0}%</b><span>自报任务完成率</span></div></div><p class="small space">统计仅来自本机操作，属于原型体验数据；不代表申报书的研究或验收成绩。</p><a class="btn outline space" href="#admin-feedback">查看体验反馈</a></section></div><section class="panel space"><div class="section-head" style="margin-top:0"><h3>最近的资料维护</h3><a class="text-btn" href="#admin-logs">生成校验记录 ${icon('arrow')}</a></div>${d.audit.length?d.audit.slice(-5).reverse().map(a=>`<div class="admin-message"><p>${E(a.summary)} · 更新至资料版本 v${a.version}</p><small>${new Date(a.at).toLocaleString('zh-CN')}</small></div>`).join(''):'<p class="small">还没有维护记录。编辑点位、路线或任务后，这里会记录资料版本。</p>'}</section>`);}
 else if(state.route==='admin-points'){layout(`${heading('LOCATION LIBRARY','点位资料管理','维护事实来源、开放条件与允许动作；关闭点位会立即阻止相关任务。',`${d.points.length} 个点位`)}<div class="toolbar"><span class="small">所有初始点位均为虚构示范，待现场核实</span><input id="admin-search" type="search" placeholder="搜索点位名称或主题" aria-label="搜索点位"></div><div class="table-wrap"><table><thead><tr><th>点位 / 主题</th><th>观察内容与来源</th><th>核实状态</th><th>开放状态</th><th>操作</th></tr></thead><tbody>${d.points.map(p=>`<tr data-search="${E(p.name+' '+p.theme)}"><td><b>${E(p.name)}</b><p>${p.id.toUpperCase()} · ${p.theme}</p></td><td><p>${E(p.fact)}</p><small>${E(p.source)}</small></td><td>${p.verifiedAt?E(p.verifiedAt):'<span class="badge warn">待实地核实</span>'}</td><td><span class="badge ${p.open?'':'warn'}">${p.open?'开放':'已关闭'}</span></td><td><div class="actions"><button class="btn outline sm" data-action="edit-point" data-id="${p.id}">编辑</button><button class="btn sm ${p.open?'danger':''}" data-action="toggle-point" data-id="${p.id}">${p.open?'关闭':'开放'}</button></div></td></tr>`).join('')}</tbody></table><div class="search-empty" id="search-empty" hidden>没有匹配的点位</div></div>`);}
 else if(state.route==='admin-routes'){layout(`${heading('ROUTE PLANNING','路线与实走计时','路径使用固定点位顺序，时间预算始终包含 20% 的缓冲。')}<div class="grid3">${d.routes.map(r=>`<section class="point-card"><div class="point-head"><span class="eyebrow">${r.id.toUpperCase()}</span><span class="badge ${r.active?'':'gray'}">${r.active?'已启用':'已停用'}</span></div><h3>${E(r.name)}</h3><p class="space">${pointNames(r).map(E).join(' → ')}</p><div class="route-meta"><span>${icon('walk')}${r.walk} 分钟步行</span><span>${icon('camera')}${r.points.length*2} 分钟停留</span></div><div class="notice">实走计时 ${r.timings.length} / 3 次<br>${r.timings.length?r.timings.map(t=>t.minutes+' 分钟').join('、'):'尚未填写实走数据'}</div><div class="inline"><button class="btn primary sm" data-action="edit-route" data-id="${r.id}">维护与计时</button><button class="btn outline sm" data-action="toggle-route" data-id="${r.id}">${r.active?'停用路线':'启用路线'}</button></div></section>`).join('')}</div>`);}
 else if(state.route==='admin-templates'){layout(`${heading('TASK LIBRARY','任务模板与审核','审核通过的模板才会用于探索；本地个性化模式按人数匹配互动动作。',`${d.templates.length} 个任务模板`)}<div class="toolbar"><span class="small">修改任务步骤后请重新审核其现场可执行性</span><input id="admin-search" type="search" placeholder="搜索任务或点位" aria-label="搜索任务"></div><div class="grid2" id="template-grid">${d.templates.map(t=>{const p=d.points.find(p=>p.id===t.pointId);return `<article class="task" data-search="${E(t.title+' '+p.name)}"><div class="task-top"><span class="task-number">${t.id.toUpperCase()} · ${E(p.name)}</span><span class="badge ${t.approved?'':'warn'}">${t.approved?'演示审核通过':'待审核'}</span></div><h3>${E(t.title)}</h3><ol>${t.steps.map(x=>`<li>${E(x)}</li>`).join('')}</ol><p class="small">双人互动：${E(t.duo)}</p><div class="inline space"><button class="btn outline sm" data-action="edit-template" data-id="${t.id}">编辑任务</button><button class="btn sm" data-action="approve-template" data-id="${t.id}">${t.approved?'撤回审核':'审核通过'}</button><span class="small">${t.minutes} 分钟 / v${t.version}</span></div></article>`;}).join('')}</div><div class="search-empty" id="search-empty" hidden>没有匹配的任务</div>`);}
 else if(state.route==='admin-feedback'){layout(`${heading('EXPERIENCE & FEEDBACK','体验与反馈','查看完成情况、跳过原因与主观反馈。个人照片不会展示给管理员。')}<div class="toolbar"><span class="small">${d.sessions.length} 次本机体验 · 自报完成</span><button class="btn outline" data-action="export-feedback">${icon('download')} 导出匿名 CSV</button></div>${d.sessions.length?`<div class="table-wrap"><table><thead><tr><th>体验记录</th><th>方式 / 人数</th><th>状态 / 耗时</th><th>任务进度</th><th>反馈</th></tr></thead><tbody>${[...d.sessions].reverse().map(s=>`<tr><td><b>${E(s.routeName)}</b><p>${s.id.slice(0,8)} · ${new Date(s.createdAt).toLocaleDateString('zh-CN')}</p></td><td>${modeText[s.preferences.mode]}<p>${s.preferences.people} 人 / ${s.preferences.budget} 分钟</p></td><td><span class="badge gray">${statusText[s.status]}</span><p>${timeString(s)}</p></td><td>${s.tasks.filter(t=>t.status==='done').length} / ${s.tasks.length} 完成${s.tasks.filter(t=>t.status==='skipped').map(t=>`<p>跳过 ${E(t.pointName)}：${E(t.reason)}</p>`).join('')}</td><td><p>${E(s.feedback||'暂未填写')}</p>${s.rating?`<small>体验评分 ${s.rating} / 5</small>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有体验反馈','在用户端完成一次探索并填写感受后，这里会显示记录。','<a class="btn primary" href="#explore">去用户端体验</a>')}`);}
 else if(state.route==='admin-logs'){layout(`${heading('GENERATION & VALIDATION','生成与约束校验','记录路线检查结果和任务来源；模板回退不计为 AI 生成成功。')}<div class="notice warn">当前未配置 AI 模型接口。“个性化任务”采用本地模板匹配并记录回退原因，无模型调用费用。</div>${d.logs.length?`<div class="table-wrap"><table><thead><tr><th>时间 / 路线</th><th>结果</th><th>预算检查</th><th>任务来源</th><th>资料版本</th></tr></thead><tbody>${[...d.logs].reverse().map(l=>`<tr><td>${E(l.route)}<p>${new Date(l.at).toLocaleString('zh-CN')}</p></td><td><span class="badge ${l.status==='模板回退'?'warn':''}">${l.status}</span></td><td>${l.total} / ${l.budget} 分钟<p>编号、开放状态、审核状态已检查</p></td><td><p>${E(l.reason)}</p></td><td>v${l.version}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有生成记录','每次用户开始探索后，检查结果会保存在这里。')}`);}
}
function editPoint(id){const p=state.admin.points.find(p=>p.id===id);modal(`<div class="dialog-head"><h2>维护点位资料</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><form id="point-form" data-id="${id}">${[['name','点位名称',p.name],['fact','可观察事实',p.fact],['source','事实来源',p.source],['condition','开放与拍摄条件',p.condition],['allowed','允许动作',p.allowed]].map(([n,l,v])=>`<label class="form-field">${l}<input name="${n}" value="${E(v)}" maxlength="2000" required></label>`).join('')}<label class="form-field">现场核实日期<input name="verifiedAt" type="date" value="${p.verifiedAt||''}"><small>尚未实地核实时保持空白。</small></label><p class="error" id="form-error"></p><button type="submit" class="btn primary full">保存资料版本</button></form>`);}
function editRoute(id){const r=state.admin.routes.find(r=>r.id===id);modal(`<div class="dialog-head"><h2>${E(r.name)}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><form id="route-form" data-id="${id}"><label class="form-field">路线步行估时（分钟）<input type="number" name="walk" min="1" max="60" step="1" value="${r.walk}" required><small>任务停留按每个点位 2 分钟计算，另加用户预算 20% 缓冲。</small></label><label class="form-field">新增一次实走步行计时（选填，分钟）<input type="number" name="timing" min="1" max="60" step="0.1" placeholder="例如 6.5"><small>历史计时：${r.timings.length?r.timings.map(t=>t.minutes).join('、'):'暂无'}</small></label><p class="error" id="form-error"></p><button class="btn primary full" type="submit">保存路线</button></form>`);}
function editTemplate(id){const t=state.admin.templates.find(t=>t.id===id);modal(`<div class="dialog-head"><h2>编辑拍摄任务</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><form id="template-form" data-id="${id}"><label class="form-field">任务标题<input name="title" value="${E(t.title)}" required maxlength="100"></label><label class="form-field">动作步骤（每行一个步骤）<textarea name="steps" rows="6" required>${E(t.steps.join('\n'))}</textarea></label><div class="notice">保存后会转为待审核。请复核动作边界，再点击“审核通过”。</div><p class="error" id="form-error"></p><button class="btn primary full" type="submit">保存并提交审核</button></form>`);}
function confirmDialog(title,desc,action,id,label){modal(`<div class="dialog-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><p>${desc}</p><div class="dialog-actions"><button class="btn outline" data-action="close">取消</button><button class="btn ${action==='confirm-delete'?'danger':'primary'}" data-action="${action}" data-id="${id}">${label}</button></div>`);}
async function refresh(){await load();await render();}
async function updateSession(id,data){const s=await api('/api/sessions/'+id,'PATCH',data);state.sessions=state.sessions.map(x=>x.id===id?s:x);return s;}
async function handleAction(action,id,btn){
 const s=active();
 if(action==='complete'){btn.disabled=true;await updateSession(s.id,{action:'task',taskId:id,status:'done'});experience();toast('已记录完成，别忘了留下一张照片');}
 else if(action==='skip'){modal(`<div class="dialog-head"><h2>记录跳过原因</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><form id="skip-form" data-id="${id}"><label class="form-field">为什么跳过这个任务？<select name="reason"><option>现场人多，不便拍摄</option><option>任务不太感兴趣</option><option>时间不足</option><option>天气不适合</option><option>动作说明不清楚</option></select></label><label class="form-field">补充说明（选填）<textarea name="detail" maxlength="200"></textarea></label><p class="error" id="form-error"></p><button type="submit" class="btn primary full">保存原因并跳过</button></form>`);}
 else if(['pause','resume'].includes(action)){await updateSession(id,{action});experience();toast(action==='pause'?'探索已暂停，计时已停止':'继续探索吧');}
 else if(action==='refresh-session'){await refresh();toast('已同步最新点位与探索状态');}
 else if(action==='exit'){confirmDialog('提前结束这次探索？','已经完成的任务、照片和进度会保留到探索手记中。','confirm-exit',id,'结束并保存');}
 else if(action==='confirm-exit'||action==='finish'){await updateSession(id,{action:action==='finish'?'finish':'exit'});closeModal();location.hash='memories';toast('探索已保存，打开手记写下感受吧');}
 else if(action==='record')recordDetail(id);
 else if(action==='delete-record')confirmDialog('删除这段探索记录？','这段记录、反馈和关联照片将从本机删除，无法恢复。已下载的手记文件不会被删除。','confirm-delete',id,'确认删除');
 else if(action==='confirm-delete'){await api('/api/sessions/'+id,'DELETE');closeModal();await refresh();toast('记录与照片已删除');}
 else if(action==='upload'){const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp';input.className='photo-input';input.dataset.ids=id;input.addEventListener('change',uploadPhoto);document.body.append(input);input.click();input.addEventListener('cancel',()=>input.remove());}
 else if(action==='remove-photo'){const [sid,tid]=id.split(':');await updateSession(sid,{action:'photo',taskId:tid,photo:null});if($('#modal').open)recordDetail(sid);else await render();toast('照片已移除');}
 else if(action==='logout'){await api('/api/logout','POST',{});await refresh();}
 else if(action==='edit-point')editPoint(id);
 else if(action==='edit-route')editRoute(id);
 else if(action==='edit-template')editTemplate(id);
 else if(action==='toggle-point'){const p=state.admin.points.find(p=>p.id===id);if(p.open)confirmDialog('关闭这个点位？','相关路线将无法开始，进行中的探索也会阻止继续完成该点位。','confirm-close-point',id,'确认关闭');else{await api('/api/admin/points/'+id,'PATCH',{open:true});await refresh();toast('点位已开放');}}
 else if(action==='confirm-close-point'){await api('/api/admin/points/'+id,'PATCH',{open:false});closeModal();await refresh();toast('点位已关闭，用户端已同步');}
 else if(action==='toggle-route'){const r=state.admin.routes.find(r=>r.id===id);await api('/api/admin/routes/'+id,'PATCH',{active:!r.active});await refresh();toast('路线状态已更新');}
 else if(action==='approve-template'){const t=state.admin.templates.find(t=>t.id===id);await api('/api/admin/templates/'+id,'PATCH',{approved:!t.approved});await refresh();toast(t.approved?'已撤回审核':'任务审核已通过');}
 else if(action==='export-feedback'){const rows=[['匿名记录编号','路线','方式','人数','时间预算','实际分钟','状态','完成任务','总任务','评分','反馈','跳过原因'],...state.admin.sessions.map(s=>[s.id.slice(0,8),s.routeName,modeText[s.preferences.mode],s.preferences.people,s.preferences.budget,(s.elapsed/60000).toFixed(1),statusText[s.status],s.tasks.filter(t=>t.status==='done').length,s.tasks.length,s.rating||'',s.feedback,s.tasks.filter(t=>t.status==='skipped').map(t=>t.pointName+':'+t.reason).join(';')])];const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');downloadBlob(csv,'探索体验反馈.csv','text/csv;charset=utf-8');toast('已导出本机体验反馈');}
}
function downloadBlob(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function uploadPhoto(event){const input=event.target,file=input.files[0];if(!file)return;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('请选择 JPG、PNG 或 WebP 照片');if(file.size>10*1024*1024)throw Error('原始照片请小于 10MB');toast('正在处理照片并清理定位信息…');const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const photo=canvas.toDataURL('image/jpeg',.86),[sid,tid]=input.dataset.ids.split(':');await updateSession(sid,{action:'photo',taskId:tid,photo});if($('#modal').open)recordDetail(sid);else await render();toast('照片已保存到本机，定位元数据已清理');}catch(e){toast(e.message);}finally{input.remove();}}
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form)),id=form.dataset.id,button=form.querySelector('[type=submit]');if(button)button.disabled=true;try{
 if(form.id==='login-form'){await api('/api/login','POST',data);await refresh();toast('欢迎进入管理工作台');}
 else if(form.id==='skip-form'){await updateSession(active().id,{action:'task',taskId:id,status:'skipped',reason:data.reason+(data.detail?'：'+data.detail:'')});closeModal();experience();toast('已记录跳过原因');}
 else if(form.id==='feedback-form'){await updateSession(id,{action:'feedback',feedback:data.feedback,rating:Number(data.rating)});closeModal();await render();toast('感受已保存到探索手记');}
 else if(form.id==='point-form'){await api('/api/admin/points/'+id,'PATCH',{...data,verifiedAt:data.verifiedAt||null});closeModal();await refresh();toast('点位资料与版本已保存');}
 else if(form.id==='route-form'){const body={walk:Number(data.walk)};if(data.timing)body.timing=Number(data.timing);await api('/api/admin/routes/'+id,'PATCH',body);closeModal();await refresh();toast('路线计时已保存');}
 else if(form.id==='template-form'){await api('/api/admin/templates/'+id,'PATCH',{title:data.title,steps:data.steps.split('\n').map(s=>s.trim()).filter(Boolean),approved:false});closeModal();await refresh();toast('任务已保存，请审核后使用');}
 }catch(e){const error=form.querySelector('#form-error');if(error)error.textContent=e.message;else toast(e.message);}finally{if(button)button.disabled=false;}});
document.addEventListener('input',event=>{if(event.target.id==='admin-search'){const q=event.target.value.trim().toLowerCase();let count=0;document.querySelectorAll('[data-search]').forEach(el=>{const visible=el.dataset.search.toLowerCase().includes(q);el.hidden=!visible;if(visible)count++;});$('#search-empty').hidden=count>0;}});
setInterval(()=>{const s=active();if(s&&$('#timer'))$('#timer').textContent=timeString(s);},1000);
setInterval(async()=>{if(document.hidden||state.route!=='experience'||$('#modal').open||!active())return;try{const latest=await api('/api/sessions'),a=active(),b=latest.find(x=>x.id===a.id);if(b&&(JSON.stringify(a.blocked)!==JSON.stringify(b.blocked)||a.status!==b.status)){state.sessions=latest;experience();toast('探索状态已更新');}}catch{}},5000);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'preview_exploration_routes',title:'预览探索路线',description:'修改可用时间并在用户端预览匹配路线，不会开始探索。',inputSchema:{type:'object',properties:{budget:{type:'integer',enum:[15,20,30]}},required:['budget'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(![15,20,30].includes(input?.budget))throw Error('时间预算必须是 15、20 或 30 分钟');state.preferences.budget=input.budget;state.plans=await api('/api/plan','POST',state.preferences);state.route='explore';location.hash='explore';explore();return {routes:state.plans.map(r=>({name:r.name,minutes:r.total,available:r.available}))};}})).catch(()=>{});}catch{}}
load().then(render).catch(e=>{$('#app').innerHTML=empty('暂时无法连接本地服务',E(e.message),'<button class="btn primary" onclick="location.reload()">重新连接</button>');});
